[UPLOADS, STORE_PRODUCTS, STORE_PROOFS, LOG_DIR].forEach((d) => fs.mkdirSync(d, { recursive: true }));

/* ------------------------------ helpers ------------------------------ */
const ah = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);
const esc = (s) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');
const isEmail = (e) => typeof e === 'string' && /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{2,}$/.test(e) && e.length <= 254;
const cleanStr = (s, max = 500) => String(s ?? '').trim().slice(0, max);
const toPaise = (rupees) => Math.round(Number(rupees) * 100);
const bool = (v) => v === true || v === 'true' || v === 'on' || v === '1' || v === 1;

function logError(err, req) {
  const line = `[${new Date().toISOString()}] ${req ? req.method + ' ' + req.originalUrl : ''} ${err && err.stack ? err.stack : err}\n`;
  console.error(line);
  fs.appendFile(path.join(LOG_DIR, 'error.log'), line, () => {});
}

function safeUnlink(dir, name) {
  if (!name) return;
  const base = path.basename(String(name));
  fs.unlink(path.join(dir, base), () => {});
  query('DELETE FROM blobs WHERE name=$1', [base]).catch(() => {});
}

// Uploaded files are also kept inside the database ("blobs"), so they survive Render restarts / redeploys
// (Render's free disk is wiped). If a file is missing on disk it is restored from the database on demand.
async function ensureFile(dir, name) {
  const base = path.basename(String(name || ''));
  if (!base) return null;
  const full = path.join(dir, base);
  if (fs.existsSync(full)) return full;
  const { rows } = await query('SELECT data FROM blobs WHERE name=$1', [base]);
  if (!rows[0]) return null;
  const tmp = full + '.' + crypto.randomBytes(4).toString('hex') + '.tmp';
  await fs.promises.writeFile(tmp, rows[0].data);
  await fs.promises.rename(tmp, full);
  return full;
}

function sniffImage(b) {
  if (!b || b.length < 12) return null;
  if (b[0] === 0x89 && b.toString('latin1', 1, 4) === 'PNG') return 'png';
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'jpg';
  if (b.toString('latin1', 0, 4) === 'RIFF' && b.toString('latin1', 8, 12) === 'WEBP') return 'webp';
  if (b.toString('latin1', 0, 3) === 'GIF') return 'gif';
  return null;
}

// security / activity log (visible to the admin in Admin -> Security log)
function audit(req, action, detail, who) {
  const u = who || (req && req.user) || {};
  query('INSERT INTO audit_log(user_id,email,action,detail,ip) VALUES ($1,$2,$3,$4,$5)', [
    u.id || null, u.email || null, action, cleanStr(detail, 300) || null, req ? req.ip : null,
  ]).catch(() => {});
}

const COMMON_PW = new Set(['password', 'password1', 'password123', '12345678', '123456789', '1234567890', 'qwerty123', 'qwertyuiop', 'iloveyou', 'admin123', 'abcd1234', '11111111', 'welcome123', 'india123']);
function pwProblem(p) {
  if (p.length < 8 || p.length > 100) return 'Password must be 8 to 100 characters';
  if (!/[A-Za-z]/.test(p) || !/\d/.test(p)) return 'Password must contain at least one letter and one number';
  if (COMMON_PW.has(p.toLowerCase())) return 'This password is too common. Please choose a stronger one';
  return null;
}
const urlOk = (v) => !v || /^https:\/\/[^\s<>"']+$/.test(v);
const imgUrlOk = (v) => !v || /^https:\/\/[^\s<>"']+$/.test(v) || /^\/uploads\/[a-f0-9]{32}\.(png|jpg|webp|gif)$/.test(v);
const DUMMY_HASH = bcrypt.hashSync('dummy-password-for-timing-9X', 10);

async function getSettings() {
  const { rows } = await query('SELECT key, value FROM settings');
  const s = {};
  rows.forEach((r) => (s[r.key] = r.value));
  return s;
}
async function setSetting(key, value) {
  await query(
    'INSERT INTO settings(key,value) VALUES ($1,$2) ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value',
    [key, String(value ?? '')]
  );
}

/* ------------------------------ email ------------------------------ */
let transporter = null;
if (process.env.SMTP_HOST) {
  try {
    transporter = require('nodemailer').createTransport({
      host: process.env.SMTP_HOST,
      port: parseInt(process.env.SMTP_PORT || '587', 10),
      secure: parseInt(process.env.SMTP_PORT || '587', 10) === 465,
      auth: process.env.SMTP_USER ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS } : undefined,
    });
  } catch (e) {
    logError(e);
  }
}
async function sendMail(to, subject, text) {
  if (!transporter) {
    console.log(`\n[EMAIL not configured - printed here]\nTo: ${to}\nSubject: ${subject}\n${text}\n`);
    return;
  }
  try {
    await transporter.sendMail({ from: process.env.MAIL_FROM || process.env.SMTP_USER, to, subject, text });
  } catch (e) {
    logError(e);
  }
}

/* ------------------------------ app setup ------------------------------ */
const app = express();
app.set('trust proxy', 1);
app.disable('x-powered-by');
let compression = null;
try { compression = require('compression'); } catch (_) { /* optional: pages are sent uncompressed if the package is missing */ }
if (compression) app.use(compression());
if (PROD) {
  // force HTTPS (Render terminates TLS and tells us the original protocol)
  app.use((req, res, next) => {
    if (req.get('x-forwarded-proto') === 'http' && req.path !== '/api/settings') return res.redirect(301, 'https://' + req.get('host') + req.originalUrl);
    next();
  });
}
app.use(
  helmet({
    contentSecurityPolicy: {
      useDefaults: true,
      directives: {
        'script-src': ["'self'", 'https://cdn.jsdelivr.net', 'https://checkout.razorpay.com'],
        'style-src': ["'self'", "'unsafe-inline'", 'https://fonts.googleapis.com'],
        'font-src': ["'self'", 'https://fonts.gstatic.com', 'data:'],
        'img-src': ["'self'", 'data:', 'https:'],
        'frame-src': ["'self'", 'https://api.razorpay.com', 'https://checkout.razorpay.com', 'https://www.youtube.com', 'https://www.youtube-nocookie.com', 'https://player.vimeo.com', 'https://drive.google.com'],
        'connect-src': ["'self'", 'https://api.razorpay.com', 'https://lumberjack.razorpay.com', 'https://cdn.jsdelivr.net'],
        'form-action': ["'self'"],
      },
    },
    crossOriginEmbedderPolicy: false,
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
    strictTransportSecurity: { maxAge: 31536000, includeSubDomains: true },
  })
);
app.use((req, res, next) => {
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), usb=(), bluetooth=()');
  res.setHeader('X-Permitted-Cross-Domain-Policies', 'none');
  if (/^\/(admin|dashboard|checkout|login|register|forgot-password)(\.html)?$/.test(req.path)) res.setHeader('X-Robots-Tag', 'noindex, nofollow');
  next();
});
app.use(rateLimit({ windowMs: 60 * 1000, limit: 600, standardHeaders: true, legacyHeaders: false, skip: (req) => req.path === '/api/webhooks/razorpay' }));
app.use(cookieParser());

// Razorpay webhook needs the RAW body for signature verification -> must be before express.json()
app.post(
  '/api/webhooks/razorpay',
  express.raw({ type: '*/*', limit: '1mb' }),
  ah(async (req, res) => {
    const signature = req.get('x-razorpay-signature') || '';
    if (!RZP_WEBHOOK_SECRET || !Buffer.isBuffer(req.body)) return res.status(400).send('not configured');
    const expected = crypto.createHmac('sha256', RZP_WEBHOOK_SECRET).update(req.body).digest('hex');
    if (!safeEqual(expected, signature)) return res.status(400).send('invalid signature');

    let event;
    try { event = JSON.parse(req.body.toString('utf8')); } catch (_) { return res.status(400).send('bad payload'); }
    if (String(event.event || '').startsWith('subscription.')) { await handleSubscriptionEvent(event); return res.json({ ok: true }); }
    const pay = event?.payload?.payment?.entity;
    const rzpOrderId = pay?.order_id || event?.payload?.order?.entity?.id;
    if (!rzpOrderId) return res.json({ ok: true });

    const { rows } = await query('SELECT * FROM orders WHERE razorpay_order_id=$1', [rzpOrderId]);
    const order = rows[0];
    if (!order) return res.json({ ok: true });

    if (event.event === 'payment.captured' || event.event === 'order.paid') {
      // amount must match what we created the order for
      if (pay && Number(pay.amount) === toPaise(order.amount) && pay.status === 'captured') {
        const done = await markPaid(order.id, pay.id);
        if (done && done.justPaid) notifyPaid(done.order);
      }
    } else if (event.event === 'payment.failed') {
      await query("UPDATE orders SET status='failed' WHERE id=$1 AND status='pending'", [order.id]);
    }
    res.json({ ok: true });
  })
);

app.use(express.json({ limit: '200kb', strict: true }));
app.use('/api', (req, res, next) => { res.setHeader('Cache-Control', 'no-store'); next(); });

// CSRF defence: cookies are SameSite=Lax and every state-changing API call must carry this custom header,
// which browsers will not add on cross-site form posts.
app.use('/api', (req, res, next) => {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next();
  if (req.get('x-requested-with') !== 'biznext' && req.get('x-bn') !== '1') return res.status(403).json({ error: 'Blocked (CSRF check)' });
  next();
});

app.use('/api', rateLimit({ windowMs: 60 * 1000, limit: 240, standardHeaders: true, legacyHeaders: false }));
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 25,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many attempts. Please try again after 15 minutes.' },
});
const downloadLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, limit: 60, standardHeaders: true, legacyHeaders: false,
  keyGenerator: (req) => 'user-' + (req.user ? req.user.id : '0'),
  message: { error: 'Too many downloads. Please try again later.' },
});
const checkoutLimiter = rateLimit({ windowMs: 15 * 60 * 1000, limit: 40, message: { error: 'Too many requests. Try later.' } });

function safeEqual(a, b) {
  const x = Buffer.from(String(a));
  const y = Buffer.from(String(b));
  return x.length === y.length && crypto.timingSafeEqual(x, y);
}

/* ------------------------------ uploads ------------------------------ */
const IMAGE_FIELDS = ['image', 'qr', 'logo', 'proof', 'icon', 'cover'];
const MIME_EXT = { 'image/png': '.png', 'image/jpeg': '.jpg', 'image/jpg': '.jpg', 'image/webp': '.webp', 'image/gif': '.gif' };
const BLOB_MAX = 60 * 1024 * 1024; // files up to 60 MB are also saved inside the database
const rawUpload = multer({
  storage: multer.diskStorage({
    destination: (req, file, cb) =>
      cb(null, file.fieldname === 'file' ? STORE_PRODUCTS : file.fieldname === 'proof' ? STORE_PROOFS : UPLOADS),
    filename: (req, file, cb) => {
      // images always get an extension that matches their real type (never .html / .svg / .js)
      const ext = IMAGE_FIELDS.includes(file.fieldname)
        ? MIME_EXT[file.mimetype] || '.png'
        : path.extname(file.originalname).toLowerCase().replace(/[^.a-z0-9]/g, '').slice(0, 10);
      cb(null, crypto.randomBytes(16).toString('hex') + ext);
    },
  }),
  limits: { fileSize: MAX_MB * 1024 * 1024, files: 3 },
  fileFilter: (req, file, cb) => {
    if (IMAGE_FIELDS.includes(file.fieldname) && !MIME_EXT[file.mimetype]) {
      return cb(new Error('Only PNG, JPG, WEBP or GIF images are allowed'));
    }
    cb(null, true);
  },
});
// runs after multer: checks the real file signature of images and keeps a copy in the database
async function postUpload(req, res, next) {
  const files = [];
  if (req.file) files.push(req.file);
  if (req.files) (Array.isArray(req.files) ? req.files : Object.values(req.files).flat()).forEach((f) => files.push(f));
  try {
    for (const f of files) {
      if (IMAGE_FIELDS.includes(f.fieldname)) {
        const fh = await fs.promises.open(f.path, 'r');
        const head = Buffer.alloc(12);
        await fh.read(head, 0, 12, 0);
        await fh.close();
        const kind = sniffImage(head);
        if (!kind) throw Object.assign(new Error('This file is not a valid PNG, JPG, WEBP or GIF image'), { status: 400 });
        const want = '.' + kind;
        if (path.extname(f.filename) !== want) {
          const nn = f.filename.replace(/\.[^.]*$/, '') + want;
          await fs.promises.rename(f.path, path.join(path.dirname(f.path), nn));
          f.filename = nn; f.path = path.join(path.dirname(f.path), nn);
        }
      }
      if (f.size > BLOB_MAX && !PERSISTENT && !IMAGE_FIELDS.includes(f.fieldname) && f.fieldname !== 'proof') {
        throw Object.assign(new Error(`This file is ${(f.size / 1048576).toFixed(0)} MB. Without a permanent disk, files over 60 MB are lost when the site restarts, so it was not saved. Please use a smaller file, paste a YouTube / Google Drive link instead, or add a permanent disk on Render (see the note in render.yaml).`), { status: 400 });
      }
      if (f.size <= BLOB_MAX) {
        const data = await fs.promises.readFile(f.path);
        await query('INSERT INTO blobs(name,kind,mime,data) VALUES ($1,$2,$3,$4) ON CONFLICT (name) DO NOTHING', [f.filename, f.fieldname, f.mimetype, data]);
      }
    }
    next();
  } catch (e) {
    files.forEach((f) => { fs.unlink(f.path, () => {}); query('DELETE FROM blobs WHERE name=$1', [f.filename]).catch(() => {}); });
    next(e);
  }
}
const upload = {
  single: (n) => [rawUpload.single(n), postUpload],
  fields: (f) => [rawUpload.fields(f), postUpload],
};

/* ------------------------------ auth ------------------------------ */
const SINGLE_DEVICE_ADMIN = false; // customers can use one device at a time; set true to apply the same rule to the admin
function issueToken(res, user, sid) {
  const adm = user.role === 'admin'; // admin sessions are shorter
  const token = jwt.sign({ id: user.id, v: user.token_version || 0, s: sid }, JWT_SECRET, { expiresIn: adm ? '1d' : '7d', algorithm: 'HS256' });
  res.cookie('token', token, { httpOnly: true, sameSite: 'lax', secure: PROD, maxAge: (adm ? 1 : 7) * 24 * 3600 * 1000, path: '/' });
}

// a new login gets a new session id, which signs the customer out of every other device
async function startSession(res, user) {
  const sid = crypto.randomBytes(16).toString('hex');
  await query('UPDATE users SET session_id=$1 WHERE id=$2', [sid, user.id]);
  issueToken(res, user, sid);
}
const loadUser = ah(async (req, res, next) => {
  const token = req.cookies && req.cookies.token;
  if (token) {
    try {
      const { id, v, s } = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] });
      const { rows } = await query(
        'SELECT id,name,email,phone,role,email_verified,is_blocked,token_version,session_id,partner_id,created_at FROM users WHERE id=$1',
        [id]
      );
      if (rows[0] && !rows[0].is_blocked && (v || 0) === rows[0].token_version) {
        const row = rows[0];
        const single = row.role !== 'admin' || SINGLE_DEVICE_ADMIN;
        const other = single && row.session_id && row.session_id !== s; // this account was opened on another device
        delete row.token_version;
        delete row.session_id;
        if (other) req.kicked = true;
        else { req.user = row; req.sid = s; }
      }
    } catch (_) {
      /* invalid token -> treated as logged out */
    }
  }
  next();
});
app.use('/api', loadUser);

const requireAuth = (req, res, next) => (req.user ? next() : req.kicked
  ? res.status(401).json({ error: 'You were logged out because this account was opened on another device. Please login again.', code: 'other_device' })
  : res.status(401).json({ error: 'Please login first' }));
const requireAdmin = (req, res, next) => {
  if (!req.user) return res.status(401).json({ error: 'Please login first' });
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Admin access only' });
  next();
};

async function createOtp(email, purpose) {
  const code = String(crypto.randomInt(100000, 1000000));
  await query('DELETE FROM otps WHERE email=$1 AND purpose=$2', [email, purpose]);
  await query("INSERT INTO otps(email,purpose,code_hash,expires_at) VALUES ($1,$2,$3, now() + interval '10 minutes')", [
    email,
    purpose,
    sha256(code + email),
  ]);
  return code;
}
async function checkOtp(email, purpose, code) {
  const { rows } = await query('SELECT * FROM otps WHERE email=$1 AND purpose=$2 AND expires_at > now()', [email, purpose]);
  const o = rows[0];
  if (!o) return false;
  if (o.attempts >= 5) return false;
  await query('UPDATE otps SET attempts = attempts + 1 WHERE id=$1', [o.id]);
  if (!safeEqual(o.code_hash, sha256(String(code) + email))) return false;
  await query('DELETE FROM otps WHERE id=$1', [o.id]);
  return true;
}

/* ------------------------------ auth routes ------------------------------ */
app.post(
  '/api/auth/register',
  authLimiter,
  ah(async (req, res) => {
    const name = cleanStr(req.body.name, 80);
    const email = cleanStr(req.body.email, 254).toLowerCase();
    const phone = cleanStr(req.body.phone, 20);
    const password = String(req.body.password || '');
    if (name.length < 2) return res.status(400).json({ error: 'Please enter your name' });
    if (!isEmail(email)) return res.status(400).json({ error: 'Enter a valid email' });
    const pwe = pwProblem(password);
    if (pwe) return res.status(400).json({ error: pwe });
    if (!/^[0-9+\-\s]{8,20}$/.test(phone) || phone10(phone).length < 10) return res.status(400).json({ error: 'Enter your 10 digit mobile number' });

    const exists = await query('SELECT id FROM users WHERE email=$1', [email]);
    if (exists.rows[0]) return res.status(409).json({ error: 'This email is already registered. Please login.' });
    if (await phoneTaken(phone)) return res.status(409).json({ error: 'This mobile number is already registered. One mobile number can have only one account. Please login.' });
    const pt = await partnerOf(req);

    const hash = await bcrypt.hash(password, 12);
    const { rows } = await query(
      "INSERT INTO users(name,email,phone,password_hash,email_verified,partner_id) VALUES ($1,$2,$3,$4,$5,$6) RETURNING id,name,email",
      [name, email, phone || null, hash, !VERIFY_REQUIRED, pt ? pt.id : null]
    );
    if (VERIFY_REQUIRED) {
      const code = await createOtp(email, 'verify');
      await sendMail(email, 'Verify your email - NextBiz Digital Company', `Your verification code is ${code}. It is valid for 10 minutes.`);
      return res.json({ ok: true, needVerify: true, email });
    }
    await startSession(res, rows[0]);
    res.json({ ok: true, needVerify: false });
  })
);

app.post(
  '/api/auth/verify-email',
  authLimiter,
  ah(async (req, res) => {
    const email = cleanStr(req.body.email, 254).toLowerCase();
    const ok = await checkOtp(email, 'verify', cleanStr(req.body.otp, 10));
    if (!ok) return res.status(400).json({ error: 'Invalid or expired code' });
    const { rows } = await query('UPDATE users SET email_verified=true WHERE email=$1 RETURNING id', [email]);
    if (rows[0]) { await startSession(res, (await query('SELECT id,role,token_version FROM users WHERE id=$1', [rows[0].id])).rows[0]); }
    res.json({ ok: true });
  })
);

app.post(
  '/api/auth/resend-otp',
  authLimiter,
  ah(async (req, res) => {
    const email = cleanStr(req.body.email, 254).toLowerCase();
    const purpose = req.body.purpose === 'reset' ? 'reset' : 'verify';
    const { rows } = await query('SELECT id, email_verified FROM users WHERE email=$1', [email]);
    if (rows[0] && (purpose === 'reset' || !rows[0].email_verified)) {
      const code = await createOtp(email, purpose);
      await sendMail(email, 'Your code - NextBiz Digital Company', `Your code is ${code}. It is valid for 10 minutes.`);
    }
    res.json({ ok: true }); // same answer whether or not the email exists
  })
);

app.post(
  '/api/auth/login',
  authLimiter,
  ah(async (req, res) => {
    const email = cleanStr(req.body.email, 254).toLowerCase();
    const password = String(req.body.password || '');
    const { rows } = await query('SELECT * FROM users WHERE email=$1', [email]);
    const u = rows[0];
    if (u && u.locked_until && new Date(u.locked_until) > new Date()) {
      audit(req, 'login_blocked_locked', email, { id: u.id, email });
      const mins = Math.max(1, Math.ceil((new Date(u.locked_until) - new Date()) / 60000));
      return res.status(429).json({ error: `Too many wrong attempts. Account locked for ${mins} more minute(s). You can also use "Forgot password".` });
    }
    const ok = !!u && (await bcrypt.compare(password, u ? u.password_hash : DUMMY_HASH));
    if (!u) await bcrypt.compare(password, DUMMY_HASH); // same response time whether or not the email exists
    if (!ok) {
      if (u) {
        const n = (u.failed_logins || 0) + 1;
        if (n >= 5) {
          await query("UPDATE users SET failed_logins=0, locked_until=now() + interval '15 minutes' WHERE id=$1", [u.id]);
          audit(req, 'account_locked', '5 wrong passwords', { id: u.id, email });
        } else await query('UPDATE users SET failed_logins=$1 WHERE id=$2', [n, u.id]);
      }
      audit(req, 'login_failed', email, { id: u ? u.id : null, email });
      return res.status(401).json({ error: 'Wrong email or password' });
    }
    await query('UPDATE users SET failed_logins=0, locked_until=NULL WHERE id=$1', [u.id]);
    if (u.is_blocked) return res.status(403).json({ error: 'Your account is blocked. Contact support.' });
    if (!u.email_verified) {
      const code = await createOtp(email, 'verify');
      await sendMail(email, 'Verify your email - NextBiz Digital Company', `Your verification code is ${code}. It is valid for 10 minutes.`);
      return res.status(403).json({ error: 'Please verify your email first', needVerify: true, email });
    }
    await startSession(res, u);
    audit(req, 'login', u.role, { id: u.id, email });
    res.json({ ok: true, role: u.role });
  })
);

