app.post(
  '/api/checkout',
  requireAuth,
  checkoutLimiter,
  ah(async (req, res) => {
    const type = ['plan', 'topic', 'all_access', 'all_software'].includes(req.body.type) ? req.body.type : 'product';
    const id = parseInt(req.body.id, 10) || 0;
    const method = req.body.method === 'manual' ? 'manual' : 'razorpay';
    const details = cleanStr(req.body.details, 1000);
    const s = await getSettings();
    const pt = await partnerOf(req);
    if (pt && method !== 'manual') return res.status(400).json({ error: 'Please pay using the QR / UPI ID shown on the payment page.' });

    let item;
    if (type === 'topic') {
      const t = (await query('SELECT id,title,price,kind FROM topics WHERE id=$1 AND is_active', [id])).rows[0];
      if (t) {
        const pa = await passAccess(req.user.id);
        if (pa.topics.has(t.id) || (pa.all && t.kind === 'tab')) return res.status(409).json({ error: 'This is already unlocked for you.' });
        item = { id: t.id, name: (t.kind === 'aicourse' ? 'Course: ' : 'Tab Pass: ') + t.title, price: t.price };
      }
    } else if (type === 'all_access') {
      const pa = await passAccess(req.user.id);
      if (pa.all) return res.status(409).json({ error: 'You already have access to all tabs.' });
      item = { id: 0, name: method === 'manual' ? 'All Tabs Access (1 month)' : 'All Tabs Monthly Pass', price: Number(s.all_access_price || 499) };
    } else if (type === 'all_software') {
      const pa = await passAccess(req.user.id);
      if (pa.software) return res.status(409).json({ error: 'You already have access to all software.' });
      item = { id: 0, name: 'All Software Pass', price: Number(s.all_software_price || 1999) };
    } else if (type === 'plan') {
      item = (await query('SELECT id,name,price FROM plans WHERE id=$1 AND is_active', [id])).rows[0];
    } else {
      item = (await query('SELECT id,name,price,file_name FROM products WHERE id=$1 AND is_active', [id])).rows[0];
      if (item) {
        const already = await query("SELECT 1 FROM orders WHERE user_id=$1 AND product_id=$2 AND status='paid' LIMIT 1", [req.user.id, id]);
        if (already.rows[0]) return res.status(409).json({ error: 'You already own this product. Find it in your dashboard.' });
      }
    }
    if (!item) return res.status(404).json({ error: 'Item not found' });
    if (Number(item.price) <= 0) return res.status(400).json({ error: 'Invalid price' });

    if (method === 'manual' && !(pt ? (pt.upi_id || pt.qr_url) : (s.manual_enabled === 'true' && (s.upi_id || s.qr_url)))) {
      return res.status(400).json({ error: 'Manual payment is not available right now' });
    }

    // "All Tabs" paid online = monthly AutoPay subscription (UPI AutoPay / card mandate)
    if (type === 'all_access' && method === 'razorpay') {
      const sub = await createSubscription(req.user, Number(item.price));
      return res.json({ ok: true, method: 'subscription', key: RZP_KEY_ID, subscriptionId: sub.rzp_sub_id, itemName: 'All Tabs - monthly AutoPay',
        user: { name: req.user.name, email: req.user.email, phone: req.user.phone || '' } });
    }
    // Price always comes from the database - never from the browser.
    const ins = await query(
      `INSERT INTO orders(user_id,item_type,product_id,plan_id,item_name,amount,method,status,details,topic_id,partner_id)
       VALUES ($1,$2,$3,$4,$5,$6,$7,'pending',$8,$9,$10) RETURNING *`,
      [req.user.id, type, type === 'product' ? id : null, type === 'plan' ? id : null, item.name, item.price, method, details || null, type === 'topic' ? id : null, pt ? pt.id : null]
    );
    const order = ins.rows[0];

    if (method === 'manual') return res.json({ ok: true, orderId: order.id, method: 'manual' });

    const rz = await rzp('/orders', 'POST', {
      amount: toPaise(order.amount),
      currency: 'INR',
      receipt: 'bn_' + order.id,
      notes: { order_id: String(order.id), user_id: String(req.user.id) },
    });
    await query('UPDATE orders SET razorpay_order_id=$1 WHERE id=$2', [rz.id, order.id]);
    res.json({
      ok: true,
      method: 'razorpay',
      orderId: order.id,
      key: RZP_KEY_ID,
      rzpOrderId: rz.id,
      amount: rz.amount,
      currency: 'INR',
      itemName: order.item_name,
      user: { name: req.user.name, email: req.user.email, phone: req.user.phone || '' },
    });
  })
);

// Browser reports success -> we verify signature AND ask Razorpay for the real payment status before delivering.
app.post(
  '/api/payments/razorpay/verify',
  requireAuth,
  checkoutLimiter,
  ah(async (req, res) => {
    const orderId = parseInt(req.body.order_id, 10) || 0;
    const rzpOrderId = cleanStr(req.body.razorpay_order_id, 100);
    const rzpPaymentId = cleanStr(req.body.razorpay_payment_id, 100);
    const signature = cleanStr(req.body.razorpay_signature, 200);

    const { rows } = await query('SELECT * FROM orders WHERE id=$1 AND user_id=$2', [orderId, req.user.id]);
    const order = rows[0];
    if (!order || order.razorpay_order_id !== rzpOrderId) return res.status(400).json({ error: 'Invalid order' });
    if (order.status === 'paid') return res.json({ ok: true, status: 'paid' });

    const expected = crypto.createHmac('sha256', RZP_KEY_SECRET).update(rzpOrderId + '|' + rzpPaymentId).digest('hex');
    if (!safeEqual(expected, signature)) {
      await query("UPDATE orders SET status='failed' WHERE id=$1 AND status='pending'", [order.id]);
      return res.status(400).json({ error: 'Payment verification failed' });
    }

    let pay = await rzp('/payments/' + encodeURIComponent(rzpPaymentId), 'GET');
    if (pay.order_id !== rzpOrderId || Number(pay.amount) !== toPaise(order.amount)) {
      return res.status(400).json({ error: 'Payment details do not match the order' });
    }
    if (pay.status === 'authorized') {
      pay = await rzp('/payments/' + encodeURIComponent(rzpPaymentId) + '/capture', 'POST', { amount: pay.amount, currency: 'INR' });
    }
    if (pay.status !== 'captured') {
      return res.status(202).json({ ok: false, status: pay.status, error: 'Payment is not completed yet. If money was deducted, it will be confirmed automatically.' });
    }
    const done = await markPaid(order.id, rzpPaymentId);
    if (done && done.justPaid) notifyPaid(done.order);
    res.json({ ok: true, status: 'paid' });
  })
);

/* ------------------------------ monthly subscription (Razorpay AutoPay mandate) ------------------------------ */
async function createSubscription(user, price) {
  const paise = toPaise(price);
  const st = await getSettings();
  let planId = st.rzp_plan_all_id;
  if (!planId || Number(st.rzp_plan_all_amount) !== paise) {
    const plan = await rzp('/plans', 'POST', {
      period: 'monthly', interval: 1,
      item: { name: 'All Tabs Monthly Pass', amount: paise, currency: 'INR', description: 'Monthly access to all tabs' },
    });
    planId = plan.id;
    await setSetting('rzp_plan_all_id', planId);
    await setSetting('rzp_plan_all_amount', String(paise));
  }
  const sub = await rzp('/subscriptions', 'POST', {
    plan_id: planId, total_count: 120, quantity: 1, customer_notify: 1,
    notes: { user_id: String(user.id), email: user.email },
  });
  const ins = await query('INSERT INTO subscriptions(user_id,rzp_sub_id,rzp_plan_id,amount,status) VALUES ($1,$2,$3,$4,$5) RETURNING *', [user.id, sub.id, planId, price, sub.status || 'created']);
  return ins.rows[0];
}

// one paid order per subscription payment (unique payment id) - this is what grants a month of access
async function recordSubscriptionPayment(sub, pay) {
  if (!pay || pay.status !== 'captured' || Number(pay.amount) !== toPaise(sub.amount)) return null;
  const ins = await query(
    `INSERT INTO orders(user_id,item_type,item_name,amount,method,status,razorpay_payment_id,paid_at)
     VALUES ($1,'all_access','All Tabs Monthly Pass',$2,'razorpay','paid',$3,now()) ON CONFLICT DO NOTHING RETURNING *`,
    [sub.user_id, sub.amount, pay.id]
  );
  const o = ins.rows[0];
  if (!o) return null;
  const inv = 'BN-' + new Date().getFullYear() + '-' + String(o.id).padStart(6, '0');
  const up = await query('UPDATE orders SET invoice_no=$1 WHERE id=$2 RETURNING *', [inv, o.id]);
  notifyPaid(up.rows[0]);
  return up.rows[0];
}

async function syncSubscription(rzpSubId) {
  const s = await rzp('/subscriptions/' + encodeURIComponent(rzpSubId), 'GET');
  await query('UPDATE subscriptions SET status=$1, current_end=$2, updated_at=now() WHERE rzp_sub_id=$3', [
    s.status, s.current_end ? new Date(s.current_end * 1000) : null, rzpSubId,
  ]);
  return s;
}

async function handleSubscriptionEvent(event) {
  const se = event?.payload?.subscription?.entity;
  if (!se || !se.id) return;
  const sub = (await query('SELECT * FROM subscriptions WHERE rzp_sub_id=$1', [se.id])).rows[0];
  if (!sub) return;
  await query('UPDATE subscriptions SET status=$1, current_end=COALESCE($2,current_end), updated_at=now() WHERE id=$3', [
    se.status || sub.status, se.current_end ? new Date(se.current_end * 1000) : null, sub.id,
  ]);
  if (event.event === 'subscription.charged') await recordSubscriptionPayment(sub, event?.payload?.payment?.entity);
}

app.post(
  '/api/subscription/verify',
  requireAuth,
  checkoutLimiter,
  ah(async (req, res) => {
    const subId = cleanStr(req.body.razorpay_subscription_id, 100);
    const payId = cleanStr(req.body.razorpay_payment_id, 100);
    const signature = cleanStr(req.body.razorpay_signature, 200);
    const sub = (await query('SELECT * FROM subscriptions WHERE rzp_sub_id=$1 AND user_id=$2', [subId, req.user.id])).rows[0];
    if (!sub) return res.status(400).json({ error: 'Invalid subscription' });
    const expected = crypto.createHmac('sha256', RZP_KEY_SECRET).update(payId + '|' + subId).digest('hex');
    if (!safeEqual(expected, signature)) return res.status(400).json({ error: 'Payment verification failed' });
    const pay = await rzp('/payments/' + encodeURIComponent(payId), 'GET');
    await syncSubscription(subId);
    if (pay.status !== 'captured') return res.status(202).json({ ok: false, error: 'Payment is not completed yet. If money was deducted it will be confirmed automatically.' });
    await recordSubscriptionPayment(sub, pay);
    res.json({ ok: true, status: 'paid' });
  })
);

