app.post(
  '/api/orders/:id/proof',
  requireAuth,
  checkoutLimiter,
  upload.single('proof'),
  ah(async (req, res) => {
    const id = parseInt(req.params.id, 10) || 0;
    const utr = cleanStr(req.body.utr, 40);
    const { rows } = await query('SELECT * FROM orders WHERE id=$1 AND user_id=$2', [id, req.user.id]);
    const o = rows[0];
    if (!o || o.method !== 'manual' || !['pending', 'awaiting_verification', 'rejected'].includes(o.status)) {
      if (req.file) safeUnlink(STORE_PROOFS, req.file.filename);
      return res.status(400).json({ error: 'This order cannot accept payment proof' });
    }
    if (!/^[A-Za-z0-9\-]{6,40}$/.test(utr)) {
      if (req.file) safeUnlink(STORE_PROOFS, req.file.filename);
      return res.status(400).json({ error: 'Enter a valid UTR / transaction ID (6 to 40 letters or numbers)' });
    }
    if (!req.file && !o.proof_file) return res.status(400).json({ error: 'Please upload the payment screenshot' });
    if (req.file && o.proof_file) safeUnlink(STORE_PROOFS, o.proof_file);
    await query("UPDATE orders SET utr=$1, proof_file=COALESCE($2, proof_file), status='awaiting_verification', admin_note=NULL WHERE id=$3", [
      utr,
      req.file ? req.file.filename : null,
      id,
    ]);
    if (!o.partner_id) query("INSERT INTO admin_alerts(kind,title,body,order_id,user_id) VALUES ('payment',$1,$2,$3,$4)", [
      `Payment proof to verify: Order #${id}`, `${req.user.name} (${req.user.email}) sent UTR ${utr} for ${o.item_name} (INR ${o.amount}). Open Orders to verify it.`, id, req.user.id,
    ]).catch((e) => logError(e));
    if (o.partner_id) partnerMail(o.partner_id, `Payment to verify: Order #${id} - INR ${o.amount}`, `${req.user.name} (${req.user.email}) sent UTR ${utr} for "${o.item_name}". Open your Partner Panel > Verify Payments.`);
    if (!o.partner_id && process.env.ADMIN_EMAIL) sendMail(process.env.ADMIN_EMAIL, `Payment to verify: Order #${id} - INR ${o.amount}`, `${req.user.name} (${req.user.email}) sent UTR ${utr} for "${o.item_name}". Open Admin > Orders to verify it.`);
    res.json({ ok: true });
  })
);

