// Which tab passes the user owns (a verified paid order is required).
async function passAccess(userId) {
  const out = { all: false, software: false, topics: new Set(), products: new Set() };
  if (!userId) return out;
  // "All Tabs" is a monthly pass: every paid month gives access for ~33 days (passes bought before 18 Nov 2026 stay lifetime).
  const { rows } = await query(
    `SELECT item_type, topic_id FROM orders WHERE user_id=$1 AND status='paid' AND (
       item_type IN ('topic','all_software')
       OR (item_type='all_access' AND (paid_at < '2026-11-18' OR paid_at > now() - interval '33 days')))`,
    [userId]
  );
  rows.forEach((r) => {
    if (r.item_type === 'all_access') out.all = true;
    else if (r.item_type === 'all_software') out.software = true;
    else if (r.topic_id) out.topics.add(r.topic_id);
  });
  // what a paid PLAN unlocks (set per plan in Admin > Pricing Plans)
  const g = await query(
    `SELECT g.kind, g.ref_id FROM orders o JOIN plan_grants g ON g.plan_id=o.plan_id
     WHERE o.user_id=$1 AND o.status='paid' AND o.item_type='plan'`, [userId]);
  g.rows.forEach((r) => {
    if (r.kind === 'all_tabs') out.all = true;
    else if (r.kind === 'all_software') out.software = true;
    else if (r.kind === 'topic') out.topics.add(r.ref_id);
    else if (r.kind === 'product') out.products.add(r.ref_id);
  });
  return out;
}

// Access rule for content: free samples need only a login; everything else needs the tab pass, All Tabs Access, or a paid order for that exact item.
async function accessProduct(userId, pid) {
  const p = (
    await query(
      'SELECT p.id,p.name,p.topic_id,p.content_type,p.is_free,p.is_active,p.file_name,p.file_original,p.delivery_link,p.video_url,t.kind AS topic_kind FROM products p LEFT JOIN topics t ON t.id=p.topic_id WHERE p.id=$1',
      [pid]
    )
  ).rows[0];
  if (!p) return null;
  if (p.is_free && p.is_active) return { p, orderId: null };
  const o = (
    await query("SELECT id FROM orders WHERE user_id=$1 AND product_id=$2 AND status='paid' ORDER BY paid_at DESC LIMIT 1", [userId, pid])
  ).rows[0];
  if (o) return { p, orderId: o.id };
  if (p.topic_id && p.is_active) {
    const pa = await passAccess(userId);
    if (pa.topics.has(p.topic_id) || (pa.all && p.topic_kind !== 'aicourse')) return { p, orderId: null };
  }
  if (p.is_active) {
    const pa = await passAccess(userId);
    if (pa.products.has(p.id)) return { p, orderId: null };
    if (p.content_type === 'software' && pa.software) return { p, orderId: null };
  }
  return null;
}

