    items.forEach((i) => (i.owned = access || direct.has(i.id) || (i.is_free && !!req.user)));
    const st = await getSettings();
    res.json({ topic, items, access, all_access: pa.all && topic.kind === 'tab', all_access_price: Number(st.all_access_price || 499) });
