admin.put('/key-requests/:id', ah(async (req, res) => {
  const id = parseInt(req.params.id, 10) || 0;
  const old = (await query('SELECT k.*, u.name AS customer, u.email FROM key_requests k JOIN users u ON u.id=k.user_id WHERE k.id=$1', [id])).rows[0];
  if (!old) return res.status(404).json({ error: 'Request not found' });
  const licenseId = cleanStr(req.body.license_id, 200) || null;
  const licenseKey = cleanStr(req.body.license_key, 500) || null;
  const softwareIds = cleanStr(req.body.software_ids, 4000) || null;
  const note = cleanStr(req.body.admin_note, 1000) || null;
  const deliver = bool(req.body.deliver);
  if (deliver && !licenseId && !licenseKey && !softwareIds) return res.status(400).json({ error: 'Enter at least the Key, the ID or the Software IDs before delivering' });
  await query(
    `UPDATE key_requests SET license_id=$1, license_key=$2, software_ids=$3, admin_note=$4,
       status=CASE WHEN $5 THEN 'delivered' ELSE status END,
       delivered_at=CASE WHEN $5 THEN COALESCE(delivered_at, now()) ELSE delivered_at END WHERE id=$6`,
    [licenseId, licenseKey, softwareIds, note, deliver, id]
  );
  if (deliver && old.email) {
    sendMail(old.email, 'Your software ID and Key are ready - NextBiz Digital Company',
      `Hi ${old.customer || ''},\n\nYour software details for "${old.item_name}" are ready.\n\n${licenseId ? 'ID: ' + licenseId + '\n' : ''}${licenseKey ? 'Key: ' + licenseKey + '\n' : ''}${softwareIds ? '\nSoftware IDs:\n' + softwareIds + '\n' : ''}${note ? '\nNote: ' + note + '\n' : ''}\nYou can also see them any time in your dashboard > Software Keys.\n\nNextBiz Digital Company`);
  }
  audit(req, deliver ? 'key_deliver' : 'key_draft', old.item_name);
  res.json({ ok: true });
}));

/* ---- main page layout: the admin chooses which sections show, their order and their headings ---- */
const HOME_SECTIONS = [
  ['hero', 'Top banner'], ['plantabs', 'Plan quick tabs'], ['demo', 'Demo (videos, PDF, software)'], ['learn', 'Category tiles'],
  ['marketing', 'Marketing (ads results)'], ['software', 'Software Store (old row)'], ['ailearn', 'AI Learn & Use Course'], ['intro', 'Introduction banner'], ['pricing', 'Pricing plans'],
  ['models', 'Business models'], ['why', 'Why NextBiz'], ['steps', 'Steps (how to start)'], ['trust', 'Extra section below steps'],
  ['faq', 'FAQ'], ['cta', 'Bottom call-to-action'],
];
const HOME_KEYS = HOME_SECTIONS.map((x) => x[0]);
function sanitizeLayout(b) {
  b = b || {};
  const order = [];
  (Array.isArray(b.order) ? b.order : []).forEach((k) => { if (HOME_KEYS.includes(k) && !order.includes(k)) order.push(k); });
  HOME_KEYS.forEach((k, i) => { if (!order.includes(k)) { const at = order.indexOf(HOME_KEYS[i - 1]); order.splice(at >= 0 ? at + 1 : order.length, 0, k); } });
  const hidden = {}, text = {};
  HOME_KEYS.forEach((k) => {
    if (b.hidden && bool(b.hidden[k])) hidden[k] = true;
    const t = b.text && b.text[k];
    if (t) {
      const o = { eyebrow: cleanStr(t.eyebrow, 80), title: cleanStr(t.title, 200), sub: cleanStr(t.sub, 400) };
      if (o.eyebrow || o.title || o.sub) text[k] = o;
    }
  });
  return { order, hidden, text };
}
async function readLayout() {
  try { const s = await getSettings(); return s.home_layout ? JSON.parse(s.home_layout) : null; } catch (_) { return null; }
}
app.get('/api/home-layout', ah(async (req, res) => {
  res.set('Cache-Control', 'no-cache');
  const saved = await readLayout();
  const L = sanitizeLayout(saved);
  if (!saved) L.hidden.software = true; // Software is a category tile now
  res.json({ layout: L });
}));
admin.get('/home-layout', ah(async (req, res) => {
  const saved = await readLayout();
  const L = sanitizeLayout(saved);
  if (!saved) L.hidden.software = true;
  res.json({ layout: L, sections: HOME_SECTIONS });
}));
admin.put('/home-layout', ah(async (req, res) => {
  if (bool(req.body && req.body.reset)) await setSetting('home_layout', '');
  else await setSetting('home_layout', JSON.stringify(sanitizeLayout(req.body)));
  audit(req, 'home_layout_edit', '');
  res.json({ ok: true });
}));

