app.get('/api/home-cats', ah(async (req, res) => {
  const { rows } = await query(
    `SELECT c.id,c.title,c.icon,c.kind, COUNT(t.id) FILTER (WHERE t.is_active AND t.kind='tab')::int AS tabs
     FROM home_categories c LEFT JOIN topics t ON t.category_id=c.id WHERE c.is_active GROUP BY c.id ORDER BY c.sort_order, c.id`);
  const uid = req.user && req.user.id;
  const isAdm = !!req.user && req.user.role === 'admin';
  const pa = await passAccess(uid);
  let own = new Set();
  if (uid && pa.topics.size) {
    const r = await query('SELECT DISTINCT category_id FROM topics WHERE id = ANY($1::int[]) AND category_id IS NOT NULL', [[...pa.topics]]);
    own = new Set(r.rows.map((x) => x.category_id));
  }
  let sw = pa.software;
  if (uid && !sw) sw = !!(await query("SELECT 1 FROM orders o JOIN products p ON p.id=o.product_id WHERE o.user_id=$1 AND o.status='paid' AND p.content_type='software' LIMIT 1", [uid])).rows[0];
  rows.forEach((c) => { c.locked = !(isAdm || (c.kind === 'software' ? sw : pa.all || own.has(c.id))); });
  res.json({ categories: rows, all_access: pa.all });
}));
