/* ---- partner panel API: a partner sees and changes only their own data ---- */
const requirePartner = ah(async (req, res, next) => {
  if (!req.user) return requireAuth(req, res, next);
  const p = (await query('SELECT * FROM partners WHERE user_id=$1', [req.user.id])).rows[0];
  if (!p) return res.status(403).json({ error: 'This is not a partner account' });
  if (!p.is_active) return res.status(403).json({ error: 'Your partner account has been closed by NextBiz. Please contact support.', code: 'partner_closed' });
  req.partner = p;
  next();
});
const partnerApi = express.Router();
partnerApi.use(requirePartner);

async function partnerOrders(pid, status) {
  const params = [pid];
  let where = 'WHERE o.partner_id=$1';
  if (status) { params.push(cleanStr(status, 30)); where += ' AND o.status=$2'; }
  return (await query(
    `SELECT o.id,o.item_name,o.amount,o.method,o.status,o.utr,o.details,o.admin_note,o.created_at,o.paid_at,(o.proof_file IS NOT NULL) AS has_proof,
            u.name AS customer,u.email,u.phone
     FROM orders o JOIN users u ON u.id=o.user_id ${where} ORDER BY o.created_at DESC LIMIT 300`, params)).rows;
}
async function partnerCustomers(pid) {
  return (await query(
    `SELECT u.id,u.name,u.email,u.phone,u.created_at,u.is_blocked,
            COUNT(o.id) FILTER (WHERE o.status='paid')::int AS orders,
            COALESCE(SUM(o.amount) FILTER (WHERE o.status='paid'),0)::float AS spent
     FROM users u LEFT JOIN orders o ON o.user_id=u.id AND o.partner_id=$1 WHERE u.partner_id=$1 GROUP BY u.id ORDER BY u.created_at DESC LIMIT 500`, [pid])).rows;
}
async function partnerStats(pid) {
  const c = (await query(
    `SELECT COUNT(*) FILTER (WHERE status='awaiting_verification')::int AS pending, COUNT(*) FILTER (WHERE status='paid')::int AS paid,
            COALESCE(SUM(amount) FILTER (WHERE status='paid'),0)::float AS earned FROM orders WHERE partner_id=$1`, [pid])).rows[0];
  c.customers = (await query('SELECT COUNT(*)::int AS n FROM users WHERE partner_id=$1', [pid])).rows[0].n;
  return c;
}
const upiOk = (u) => !u || /^[\w.\-]{2,}@[A-Za-z]{2,}$/.test(u);
const waClean = (v) => {
  let n = String(v || '').replace(/\D/g, '');
  if (n.length === 10) n = '91' + n;
  return n;
};
async function setPartnerFile(pid, col, file) {
  const old = (await query('SELECT ' + col + ' AS v FROM partners WHERE id=$1', [pid])).rows[0];
  if (old && old.v && old.v.startsWith('/uploads/')) safeUnlink(UPLOADS, old.v.slice(9));
  await query('UPDATE partners SET ' + col + '=$1 WHERE id=$2', [file ? '/uploads/' + file.filename : null, pid]);
  clearPartnerCache();
}

