function partnerMail(pid, subject, text) {
  query('SELECT u.email FROM partners p JOIN users u ON u.id=p.user_id WHERE p.id=$1', [pid])
    .then((r) => { if (r.rows[0]) sendMail(r.rows[0].email, subject, text); })
    .catch((e) => logError(e));
}

