/* ------------------------------ Partner coins: 1 rupee = 1 coin. Every order a partner approves costs its price in coins. ------------------------------ */
const COIN_SQL = `
ALTER TABLE partners ADD COLUMN IF NOT EXISTS coins INT NOT NULL DEFAULT 0;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS coins_charged INT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS coin_ledger (
  id            SERIAL PRIMARY KEY,
  partner_id    INT NOT NULL REFERENCES partners(id),
  delta         INT NOT NULL,
  balance_after INT NOT NULL,
  reason        TEXT NOT NULL,
  note          TEXT,
  order_id      INT,
  created_by    INT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_coin_ledger_partner ON coin_ledger(partner_id, id DESC);
`;

// Changes a partner's balance and writes the history row in one step. Returns the new balance, or null when it would go below zero.
async function coinMove(pid, delta, reason, note, orderId, byUser) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const r = await client.query('UPDATE partners SET coins = coins + $1 WHERE id=$2 AND coins + $1 >= 0 RETURNING coins', [delta, pid]);
    if (!r.rows[0]) { await client.query('ROLLBACK'); return null; }
    await client.query('INSERT INTO coin_ledger(partner_id,delta,balance_after,reason,note,order_id,created_by) VALUES ($1,$2,$3,$4,$5,$6,$7)',
      [pid, delta, r.rows[0].coins, reason, note || null, orderId || null, byUser || null]);
    await client.query('COMMIT');
    clearPartnerCache();
    return r.rows[0].coins;
  } catch (e) {
    await client.query('ROLLBACK').catch(() => {});
    throw e;
  } finally {
    client.release();
  }
}

// Approves a manual order. A partner's order costs its price in coins (499 rupee order = 499 coins). Used by the partner and by the Super Admin.
async function approveOrder(o, user) {
  const cost = o.partner_id ? Math.ceil(Number(o.amount) || 0) : 0;
  let bal = null;
  if (cost > 0) {
    bal = await coinMove(o.partner_id, -cost, 'order', `Order #${o.id} - ${o.item_name}`, o.id, user.id);
    if (bal === null) {
      const cur = (await query('SELECT coins FROM partners WHERE id=$1', [o.partner_id])).rows[0];
      return { error: `Not enough coins. This order needs ${cost} coins but the balance is ${cur ? cur.coins : 0}. Please ask NextBiz to add coins.` };
    }
  }
  let done;
  try {
    done = await markPaid(o.id, null);
  } catch (e) {
    if (cost > 0) await coinMove(o.partner_id, cost, 'refund', `Order #${o.id} could not be approved`, o.id, user.id).catch(() => {});
    throw e;
  }
  if (!done || !done.justPaid) {
    if (cost > 0) await coinMove(o.partner_id, cost, 'refund', `Order #${o.id} was already approved`, o.id, user.id).catch(() => {});
    return { ok: true, coins: bal };
  }
  if (cost > 0) await query('UPDATE orders SET coins_charged=$1 WHERE id=$2', [cost, o.id]);
  notifyPaid(done.order);
  return { ok: true, coins: bal === null ? null : bal };
}

