const IMG_MIME = { '.png': 'image/png', '.jpg': 'image/jpeg', '.webp': 'image/webp', '.gif': 'image/gif' };
app.get('/uploads/:name', ah(async (req, res, next) => {
  const name = req.params.name;
  const mime = IMG_MIME[path.extname(name).toLowerCase()];
  if (!mime || !/^[a-f0-9]{32}\.[a-z]{3,4}$/.test(name)) return next();
  const full = await ensureFile(UPLOADS, name); // restores from the database if the disk was wiped
  if (!full) return next();
  res.sendFile(full, { headers: { 'Content-Type': mime, 'Cache-Control': 'public, max-age=86400', 'Content-Security-Policy': "default-src 'none'; sandbox", 'X-Content-Type-Options': 'nosniff' } });
}));
const PWA_TYPES = { '/manifest.webmanifest': 'application/manifest+json', '/sw.js': 'text/javascript; charset=utf-8', '/icon-192.png': 'image/png', '/icon-512.png': 'image/png', '/icon-maskable.png': 'image/png' };
app.get(Object.keys(PWA_TYPES), (req, res) => {
  res.set({ 'Content-Type': PWA_TYPES[req.path], 'Cache-Control': req.path === '/sw.js' ? 'no-cache' : 'public, max-age=86400' });
  const a = ASSETS[req.path.slice(1)]; res.send(a.t === 'png' ? Buffer.from(a.b, 'base64') : a.b);
});
app.get('/logo.png', (req, res) => { res.set('Cache-Control', 'public, max-age=3600'); res.type('png').send(Buffer.from(ASSETS['logo.png'].b, 'base64')); });
// Website files are served from the embedded ASSETS (nothing else on the server is ever exposed).
function sendAsset(res, key, status) {
  const a = Object.prototype.hasOwnProperty.call(ASSETS, key) ? ASSETS[key] : null;
  if (!a) return false;
  res.set('Cache-Control', 'no-cache');
  res.status(status || 200).type(a.t).send(a.b);
  return true;
}
app.get('/style.css', (req, res, next) => sendAsset(res, 'style.css') || next());
app.get('/js/:name', (req, res, next) => sendAsset(res, 'fe-' + path.basename(req.params.name)) || next());
